mapper.select:
		SELECT
		
		FROM tb_notification n
		LEFT JOIN tb_user u
		ON u.user_id = n.sender_user_id
		WHERE n.notification_id = #{notificationId}
		AND n.recipient_user_id = #{recipientUserId}

mapper.update:
		UPDATE tb_notification
		SET is_read = 1,
		read_at = CURRENT_TIMESTAMP
		WHERE notification_id = #{notificationId}
		AND recipient_user_id = #{recipientUserId}
		AND is_read = 0
